package dev.jobflow.security;
import dev.jobflow.domain.Role; import io.jsonwebtoken.Claims; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import java.util.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter { private final JwtService jwt; public JwtAuthenticationFilter(JwtService j){jwt=j;} @Override protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException {String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{Claims claims=jwt.parse(h.substring(7));AuthenticatedUser u=new AuthenticatedUser(UUID.fromString(claims.getSubject()),Role.valueOf(claims.get("role",String.class)));var a=new UsernamePasswordAuthenticationToken(u,null,List.of(new SimpleGrantedAuthority("ROLE_"+u.role().name())));SecurityContextHolder.getContext().setAuthentication(a);}catch(Exception ignored){SecurityContextHolder.clearContext();}c.doFilter(r,s);} }
